questionvariables.text:
qq/*Defining the question*/
coeff_x:rand(3)+1;
root:rand(5)+1;
f_y:((y-root)^2)/coeff_x;
eq1:coeff_x*x=(y-root)^2;
func:rhs(solve(eq1,y)[1]);
bb: expand(y*f_y);
cc:int(bb,y);
area_y: 2*%pi*y*f_y; /*The area of the cylinder*/
volume_y: int(area_y,y,0,root); /*The volume of the solid*/
x_1:ev(eq1,x,y=0);
xx:rhs(solve(x_1)[1]);
x_2:ev(eq1,y,x=0);
yy:rhs(solve(x_2)[1]);

/*Model answer*/
ta:volume_y;

feedbackvariables.text:
/*node 1:checks for correct answers*/

/*node 2:Integrating the indefinite integral without the limits.*/
mistake_1:int(bb,y);
/*node 3:Interchanging the limits of integration, however, with the correct definite integral*/
mistake_2:%pi*int(bb,y,2,0);
